@MainActor
final class ExhibitScreen {
    private(set) var text = "Загрузка"
    func start(id: Int) -> Task<Void, Never> {
        Task {
            do {
                let value = try await loadExhibit(id: id)
                if Task.isCancelled {
                    text = "Отменено"
                    return
                }
                text = value
            } catch is CancellationError {
                text = "Отменено"
            } catch {
                text = "Нет экспоната"
            }
        }
    }
}

